import React, { useState, useEffect, useRef } from 'react';
import { Navigate } from 'react-router-dom';
import { useApp } from '../context/AppContext';
import {
  Timer,
  Play,
  Pause,
  RotateCcw,
  Settings,
  Plus,
  Clock,
  Target,
  TrendingUp,
  Coffee,
  Brain
} from 'lucide-react';

interface TimerSettings {
  workDuration: number;
  breakDuration: number;
  longBreakDuration: number;
  sessionsUntilLongBreak: number;
}

interface SessionLog {
  duration: number;
  subject: string;
  notes: string;
  completedAt: string;
  type: 'work' | 'break' | 'long-break';
}

const TimerPage: React.FC = () => {
  const { user, studySessions, addStudySession, darkMode } = useApp();
  const [isRunning, setIsRunning] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [timeLeft, setTimeLeft] = useState(25 * 60); // 25 minutes in seconds
  const [currentSession, setCurrentSession] = useState<'work' | 'break' | 'long-break'>('work');
  const [sessionCount, setSessionCount] = useState(0);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSessionComplete, setIsSessionComplete] = useState(false);
  const [showSessionLog, setShowSessionLog] = useState(false);
  const [sessionNote, setSessionNote] = useState('');
  const [sessionSubject, setSessionSubject] = useState('');

  const [settings, setSettings] = useState<TimerSettings>({
    workDuration: 25,
    breakDuration: 5,
    longBreakDuration: 15,
    sessionsUntilLongBreak: 4
  });

  const audioRef = useRef<HTMLAudioElement>(null);

  /* Removed conditional early return to fix Hook rule violation */
  /* if (!user) ... logic moved to bottom */

  // Load settings from localStorage
  useEffect(() => {
    const savedSettings = localStorage.getItem('timerSettings');
    if (savedSettings) {
      setSettings(JSON.parse(savedSettings));
    }
  }, []);

  // Save settings to localStorage
  useEffect(() => {
    localStorage.setItem('timerSettings', JSON.stringify(settings));
  }, [settings]);

  // Timer effect
  useEffect(() => {
    let interval: NodeJS.Timeout;

    if (isRunning && !isPaused && timeLeft > 0) {
      interval = setInterval(() => {
        setTimeLeft(prev => prev - 1);
      }, 1000);
    } else if (timeLeft === 0 && isRunning) {
      handleSessionComplete();
    }

    return () => clearInterval(interval);
  }, [isRunning, isPaused, timeLeft]);

  const handleSessionComplete = () => {
    setIsRunning(false);
    setIsPaused(false);
    setIsSessionComplete(true);

    // Play notification sound
    if (audioRef.current) {
      audioRef.current.play();
    }

    // Log the session
    const sessionDuration = currentSession === 'work' ? settings.workDuration :
      currentSession === 'break' ? settings.breakDuration :
        settings.longBreakDuration;

    const newSession: SessionLog = {
      duration: sessionDuration,
      subject: sessionSubject,
      notes: sessionNote,
      completedAt: new Date().toISOString(),
      type: currentSession
    };

    addStudySession({
      duration: sessionDuration,
      subject: sessionSubject,
      notes: sessionNote
    });

    // Auto-transition to next session
    setTimeout(() => {
      if (currentSession === 'work') {
        const newCount = sessionCount + 1;
        setSessionCount(newCount);

        if (newCount % settings.sessionsUntilLongBreak === 0) {
          setCurrentSession('long-break');
          setTimeLeft(settings.longBreakDuration * 60);
        } else {
          setCurrentSession('break');
          setTimeLeft(settings.breakDuration * 60);
        }
      } else {
        setCurrentSession('work');
        setTimeLeft(settings.workDuration * 60);
      }

      setIsSessionComplete(false);
      setSessionNote('');
      setSessionSubject('');
    }, 3000);
  };

  const startTimer = () => {
    setIsRunning(true);
    setIsPaused(false);
  };

  const pauseTimer = () => {
    setIsPaused(true);
  };

  const resumeTimer = () => {
    setIsPaused(false);
  };

  const resetTimer = () => {
    setIsRunning(false);
    setIsPaused(false);
    setTimeLeft(settings.workDuration * 60);
    setCurrentSession('work');
    setSessionCount(0);
    setIsSessionComplete(false);
    setSessionNote('');
    setSessionSubject('');
  };

  const skipSession = () => {
    setIsRunning(false);
    setIsPaused(false);

    if (currentSession === 'work') {
      const newCount = sessionCount + 1;
      setSessionCount(newCount);

      if (newCount % settings.sessionsUntilLongBreak === 0) {
        setCurrentSession('long-break');
        setTimeLeft(settings.longBreakDuration * 60);
      } else {
        setCurrentSession('break');
        setTimeLeft(settings.breakDuration * 60);
      }
    } else {
      setCurrentSession('work');
      setTimeLeft(settings.workDuration * 60);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const getSessionTitle = () => {
    switch (currentSession) {
      case 'work': return 'Focus Time';
      case 'break': return 'Short Break';
      case 'long-break': return 'Long Break';
      default: return 'Timer';
    }
  };

  const getSessionIcon = () => {
    switch (currentSession) {
      case 'work': return <Brain className="w-6 h-6" />;
      case 'break': return <Coffee className="w-6 h-6" />;
      case 'long-break': return <Coffee className="w-6 h-6" />;
      default: return <Timer className="w-6 h-6" />;
    }
  };

  const getSessionColor = () => {
    switch (currentSession) {
      case 'work': return 'text-blue-600 dark:text-blue-400';
      case 'break': return 'text-green-600 dark:text-green-400';
      case 'long-break': return 'text-purple-600 dark:text-purple-400';
      default: return 'text-gray-600 dark:text-gray-400';
    }
  };

  const getSessionBgColor = () => {
    switch (currentSession) {
      case 'work': return 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800';
      case 'break': return 'bg-green-50 dark:bg-green-900/20 border-green-200 dark:border-green-800';
      case 'long-break': return 'bg-purple-50 dark:bg-purple-900/20 border-purple-200 dark:border-purple-800';
      default: return 'bg-gray-50 dark:bg-gray-800 border-gray-200 dark:border-gray-700';
    }
  };

  // Calculate statistics
  const todayStudyTime = studySessions
    .filter(session => new Date(session.completedAt).toDateString() === new Date().toDateString())
    .reduce((total, session) => total + session.duration, 0);

  const weekStudyTime = studySessions
    .filter(session => {
      const sessionDate = new Date(session.completedAt);
      const weekStart = new Date();
      weekStart.setDate(weekStart.getDate() - weekStart.getDay());
      return sessionDate >= weekStart;
    })
    .reduce((total, session) => total + session.duration, 0);

  const totalSessions = studySessions.length;
  const todaySessions = studySessions.filter(session =>
    new Date(session.completedAt).toDateString() === new Date().toDateString()
  ).length;

  return (
    <div className="space-y-6">
      {/* Audio for notifications */}
      <audio ref={audioRef} preload="auto">
        <source src="data:audio/wav;base64," type="audio/wav" />
      </audio>

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
            Study Timer
          </h1>
          <p className="text-gray-600 dark:text-gray-300 mt-2">
            Pomodoro timer for focused study sessions
          </p>
        </div>
        <button
          onClick={() => setIsSettingsOpen(true)}
          className="btn-secondary"
        >
          <Settings className="w-4 h-4 mr-2" />
          Settings
        </button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Today</p>
              <p className="text-2xl font-bold text-blue-600">{Math.floor(todayStudyTime / 60)}h {todayStudyTime % 60}m</p>
            </div>
            <Clock className="w-8 h-8 text-blue-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">This Week</p>
              <p className="text-2xl font-bold text-green-600">{Math.floor(weekStudyTime / 60)}h {weekStudyTime % 60}m</p>
            </div>
            <TrendingUp className="w-8 h-8 text-green-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Today Sessions</p>
              <p className="text-2xl font-bold text-purple-600">{todaySessions}</p>
            </div>
            <Target className="w-8 h-8 text-purple-500" />
          </div>
        </div>
        <div className="card p-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">Total Sessions</p>
              <p className="text-2xl font-bold text-orange-600">{totalSessions}</p>
            </div>
            <Timer className="w-8 h-8 text-orange-500" />
          </div>
        </div>
      </div>

      {/* Main Timer */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2">
          <div className={`card p-8 text-center ${getSessionBgColor()}`}>
            {/* Session Type */}
            <div className="flex items-center justify-center gap-2 mb-6">
              {getSessionIcon()}
              <h2 className={`text-2xl font-bold ${getSessionColor()}`}>
                {getSessionTitle()}
              </h2>
            </div>

            {/* Timer Display */}
            <div className="text-7xl font-mono font-bold text-gray-900 dark:text-white mb-8">
              {formatTime(timeLeft)}
            </div>

            {/* Progress Bar */}
            <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2 mb-8">
              <div
                className={`h-2 rounded-full transition-all duration-1000 ${currentSession === 'work' ? 'bg-blue-600' :
                    currentSession === 'break' ? 'bg-green-600' :
                      'bg-purple-600'
                  }`}
                style={{
                  width: `${((settings.workDuration * 60 - timeLeft) / (settings.workDuration * 60)) * 100}%`
                }}
              />
            </div>

            {/* Control Buttons */}
            <div className="flex justify-center gap-4">
              {!isRunning ? (
                <button
                  onClick={startTimer}
                  className="btn-primary px-8 py-3 text-lg"
                >
                  <Play className="w-5 h-5 mr-2" />
                  Start
                </button>
              ) : (
                <>
                  {isPaused ? (
                    <button
                      onClick={resumeTimer}
                      className="btn-primary px-8 py-3 text-lg"
                    >
                      <Play className="w-5 h-5 mr-2" />
                      Resume
                    </button>
                  ) : (
                    <button
                      onClick={pauseTimer}
                      className="btn-secondary px-8 py-3 text-lg"
                    >
                      <Pause className="w-5 h-5 mr-2" />
                      Pause
                    </button>
                  )}
                  <button
                    onClick={skipSession}
                    className="btn-secondary px-8 py-3 text-lg"
                  >
                    Skip
                  </button>
                </>
              )}
              <button
                onClick={resetTimer}
                className="btn-secondary px-8 py-3 text-lg"
              >
                <RotateCcw className="w-5 h-5 mr-2" />
                Reset
              </button>
            </div>

            {/* Session Counter */}
            <div className="mt-6 text-center">
              <p className="text-sm text-gray-600 dark:text-gray-400">
                Session {sessionCount + 1} of {settings.sessionsUntilLongBreak}
              </p>
            </div>
          </div>
        </div>

        {/* Side Panel */}
        <div className="space-y-6">
          {/* Quick Settings */}
          <div className="card p-4">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
              Quick Settings
            </h3>
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-600 dark:text-gray-300">Focus</span>
                <span className="text-sm font-medium">{settings.workDuration} min</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-600 dark:text-gray-300">Short Break</span>
                <span className="text-sm font-medium">{settings.breakDuration} min</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-sm text-gray-600 dark:text-gray-300">Long Break</span>
                <span className="text-sm font-medium">{settings.longBreakDuration} min</span>
              </div>
            </div>
          </div>

          {/* Current Session Notes */}
          <div className="card p-4">
            <h3 className="text-lg font-semibold text-gray-900 dark:text-white mb-4">
              Current Session
            </h3>
            <div className="space-y-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Subject
                </label>
                <input
                  type="text"
                  value={sessionSubject}
                  onChange={(e) => setSessionSubject(e.target.value)}
                  className="input w-full text-sm"
                  placeholder="What are you studying?"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Notes
                </label>
                <textarea
                  value={sessionNote}
                  onChange={(e) => setSessionNote(e.target.value)}
                  className="input w-full resize-none text-sm"
                  rows={3}
                  placeholder="Add session notes..."
                />
              </div>
            </div>
          </div>

          {/* Recent Sessions */}
          <div className="card p-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                Recent Sessions
              </h3>
              <button
                onClick={() => setShowSessionLog(!showSessionLog)}
                className="text-primary-600 hover:text-primary-500 text-sm"
              >
                {showSessionLog ? 'Hide' : 'Show'}
              </button>
            </div>

            {showSessionLog ? (
              <div className="space-y-2 max-h-48 overflow-y-auto">
                {studySessions.slice(-5).reverse().map((session, index) => (
                  <div key={index} className="text-sm p-2 bg-gray-50 dark:bg-gray-800 rounded">
                    <div className="flex justify-between items-start">
                      <div className="flex-1">
                        <p className="font-medium text-gray-900 dark:text-white">
                          {session.subject || 'Study Session'}
                        </p>
                        <p className="text-gray-600 dark:text-gray-400 text-xs">
                          {session.duration} min • {new Date(session.completedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </p>
                      </div>
                    </div>
                    {session.notes && (
                      <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                        {session.notes}
                      </p>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-sm text-gray-500 dark:text-gray-400">
                Click show to view recent sessions
              </p>
            )}
          </div>
        </div>
      </div>

      {/* Session Complete Modal */}
      {isSessionComplete && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className={`card p-6 max-w-md w-full ${getSessionBgColor()}`}>
            <div className="text-center">
              {getSessionIcon()}
              <h2 className="text-2xl font-bold text-gray-900 dark:text-white mt-4 mb-2">
                {currentSession === 'work' ? 'Great work!' : 'Break time!'}
              </h2>
              <p className="text-gray-600 dark:text-gray-300 mb-4">
                {currentSession === 'work'
                  ? 'You completed a focus session. Time for a break!'
                  : 'Break is over. Ready for another focus session?'}
              </p>
              <button
                onClick={() => setIsSessionComplete(false)}
                className="btn-primary"
              >
                Continue
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="card w-full max-w-md">
            <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white">
                Timer Settings
              </h2>
              <button
                onClick={() => setIsSettingsOpen(false)}
                className="p-2 text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
              >
                <RotateCcw className="w-5 h-5" />
              </button>
            </div>

            <div className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Focus Duration (minutes)
                </label>
                <input
                  type="number"
                  min="1"
                  max="60"
                  value={settings.workDuration}
                  onChange={(e) => setSettings({ ...settings, workDuration: parseInt(e.target.value) || 25 })}
                  className="input w-full"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Short Break Duration (minutes)
                </label>
                <input
                  type="number"
                  min="1"
                  max="30"
                  value={settings.breakDuration}
                  onChange={(e) => setSettings({ ...settings, breakDuration: parseInt(e.target.value) || 5 })}
                  className="input w-full"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Long Break Duration (minutes)
                </label>
                <input
                  type="number"
                  min="1"
                  max="60"
                  value={settings.longBreakDuration}
                  onChange={(e) => setSettings({ ...settings, longBreakDuration: parseInt(e.target.value) || 15 })}
                  className="input w-full"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                  Sessions Until Long Break
                </label>
                <input
                  type="number"
                  min="2"
                  max="10"
                  value={settings.sessionsUntilLongBreak}
                  onChange={(e) => setSettings({ ...settings, sessionsUntilLongBreak: parseInt(e.target.value) || 4 })}
                  className="input w-full"
                />
              </div>

              <button
                onClick={() => setIsSettingsOpen(false)}
                className="btn-primary w-full"
              >
                Save Settings
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TimerPage;
